package com.ecommerce.notification.service;
import com.ecommerce.notification.model.*;import com.ecommerce.notification.repo.*;import com.fasterxml.jackson.databind.JsonNode;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class EventConsumer {
 private final SmsDeliveryRepository sms;private final InboxRepository inbox;private final NotificationRepository notifications;private final WatcherRepository watchers;private final EmailDeliveryRepository emails;
 public EventConsumer(InboxRepository i,NotificationRepository n,WatcherRepository w,EmailDeliveryRepository e,SmsDeliveryRepository s){sms=s;inbox=i;notifications=n;watchers=w;emails=e;}
 @Transactional public void accept(JsonNode event){String id=event.path("id").asText();if(id.isBlank()||id.length()>128)throw new IllegalArgumentException("Event ID required");if(inbox.existsById(id))return;var p=event.path("payload");String kind=event.path("kind").asText();
 switch(kind){
 case "NOTIFY" -> send(id,p.path("customerId").asLong(),p.path("type").asText(),p.path("message").asText(),p.path("subject").asText(),p.path("html").asText());
 case "WISHLIST_CHANGED" -> {String key=p.path("customerId").asLong()+":"+p.path("productId").asLong();var w=watchers.findById(key).orElseGet(Watcher::new);long version=p.path("version").asLong();if(w.id==null||version>=w.sourceVersion){w.id=key;w.customerId=p.path("customerId").asLong();w.productId=p.path("productId").asLong();w.active=p.path("active").asBoolean();w.sourceVersion=version;watchers.save(w);}}
 case "PRICE_CHANGED","STOCK_CHANGED" -> {Set<Long> customers=new HashSet<>();String message=null,type="RESTOCK";if(kind.equals("PRICE_CHANGED")&&!p.path("oldPrice").isNull()&&p.path("newPrice").decimalValue().compareTo(p.path("oldPrice").decimalValue())<0){type="OFFER";message=p.path("productName").asText()+" price dropped to â‚¹"+p.path("newPrice").asText();watchers.findByProductIdAndActiveTrue(p.path("productId").asLong()).forEach(w->customers.add(w.customerId));}else if(kind.equals("STOCK_CHANGED")&&p.path("stock").asInt()>0&&p.path("previousStock").asInt()<=0){message=p.path("productName").asText()+" is back in stock.";watchers.findByProductIdAndActiveTrue(p.path("productId").asLong()).forEach(w->customers.add(w.customerId));p.path("restockCustomerIds").forEach(c->customers.add(c.asLong()));}if(message!=null)for(Long customer:customers)send(id+":"+customer,customer,type,message,message,message);}
 case "COUPON_OFFER" -> {for(var customer:p.path("customerIds"))send(id+":"+customer.asLong(),customer.asLong(),"OFFER","New offer: "+p.path("code").asText()+" â€” "+p.path("description").asText(),"New ShopEase offer",p.path("description").asText());}
 default -> throw new IllegalArgumentException("Unsupported notification event");}
 var receipt=new InboxReceipt();receipt.id=id;inbox.saveAndFlush(receipt);
 }
 private void send(String id,Long customerId,String type,String message,String subject,String html){if(customerId==null||customerId<=0)throw new IllegalArgumentException("Customer required");var n=new Notification();n.setCustomerId(customerId);n.setType(type);n.setMessage(message);notifications.save(n);var email=new EmailDelivery();email.id=id;email.customerId=customerId;email.subject=subject;email.html=html;email.state="PENDING";email.nextAttemptAt=java.time.Instant.now();emails.save(email);var text=new SmsDelivery();text.id=id;text.customerId=customerId;text.message=message;text.state="PENDING";text.nextAttemptAt=java.time.Instant.now();sms.save(text);}
}